    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is considered the legal and ethical "Floor" for informed consent, focusing on what a physician in the same community would typically disclose?', '["The Reasonable Patient Standard", "The Professional (Customary) Standard", "The Subjective Standard", "The Ideal Standard"]', 1, 'The Professional (or Customary) Standard focuses on the practices of the medical community. The "Reasonable Patient Standard" (modern standard) focuses on what a typical patient would want to know.'),
    (v_topic_id, 'To be valid, informed consent must include all of the following elements EXCEPT:', '["Disclosure of risks, benefits, and alternatives", "A signed document witnessed by a notary", "The patient''s decision-making capacity", "Voluntariness (absence of coercion)"]', 1, 'While documentation is important, a notary is not a requirement for valid medical informed consent. The core elements are Disclosure, Capacity, Comprehension, and Voluntariness.'),
    (v_topic_id, 'A patient is being treated for a minor infection. The physician explains the treatment but does not mention a 1 in 1,000,000 risk of a mild rash. Under the "Reasonable Patient Standard," is this likely a violation of informed consent?', '["Yes, all risks must be disclosed", "No, because a reasonable patient would not likely find this information significant in making the decision", "Yes, if the doctor knew about it", "No, only life-threatening risks must be disclosed"]', 1, 'The Reasonable Patient Standard only requires the disclosure of information that a "reasonable person" in the patient''s position would find material to their decision.'),
    (v_topic_id, 'Which exception to informed consent allows a physician to withhold information if they believe disclosure would cause the patient serious physical or psychological harm (e.g., triggering a heart attack or suicide)?', '["Emergency Exception", "Therapeutic Privilege", "Waiver of Consent", "Implied Consent"]', 1, 'Therapeutic Privilege is a rare and controversial exception. It should not be used just to avoid "upsetting" a patient, but only when disclosure poses a significant clinical danger.'),
    (v_topic_id, 'A patient tells their surgeon, "I trust you completely, just do what you think is best and don''t tell me any of the scary details." This is an example of:', '["Implied Consent", "Incompetence", "Waiver of Informed Consent", "Paternalism"]', 2, 'A competent patient has the right to "waive" their right to be informed, as long as the waiver itself is voluntary and informed.'),
    (v_topic_id, 'In a life-threatening emergency where the patient is unconscious and no surrogate is available, what is the legal justification for proceeding with treatment?', '["Paternalism", "Presumed (Implied) Consent", "Substituted Judgment", "The Rule of Rescue"]', 1, 'In emergencies where delay would cause death or serious permanent harm, consent is presumed because it is assumed a reasonable person would want life-saving care.'),
    (v_topic_id, 'A patient signs a consent form while under the influence of high-dose sedatives. Why is this consent likely invalid?', '["The disclosure was inadequate", "The patient lacked decision-making capacity at the time of signing", "The signature was not witnessed", "Sedatives are illegal"]', 1, 'Capacity is a prerequisite for consent. Being acutely intoxicated or sedated impairs the "Understanding" and "Reasoning" elements of capacity.'),
    (v_topic_id, 'Which of the following is NOT one of the four clinical elements used to assess decision-making capacity?', '["Ability to communicate a choice", "Ability to understand relevant information", "Ability to pay for the procedure", "Ability to reason through the options"]', 2, 'The four elements are: Communication of Choice, Understanding, Appreciation of Consequences, and Rationalization/Reasoning.'),
    (v_topic_id, 'If a patient understands the risks of a surgery but does not believe those risks apply to *them* specifically (e.g., due to a delusional belief), which element of capacity is impaired?', '["Communication", "Understanding", "Appreciation", "Reasoning"]', 2, 'Appreciation refers to the ability to apply the information to one''s own personal situation.'),
    (v_topic_id, 'A physician provides all the necessary information, but the patient is being pressured by their spouse to agree to the surgery. Which element of consent is compromised?', '["Disclosure", "Capacity", "Comprehension", "Voluntariness"]', 3, 'Voluntariness requires that the patient make the decision free from coercion or undue influence.'),
    (v_topic_id, 'The "Canterbury v. Spence" case was landmark because it shifted the legal standard for disclosure from:', '["Customary to Reasonable Patient", "Reasonable Patient to Customary", "Emergency to Non-emergency", "None of the above"]', 0, 'This case established the "Reasonable Patient Standard" (materiality) in US law.'),
    (v_topic_id, 'A "Material Risk" is defined as a risk that:', '["Has a 5% or higher chance of occurring", "A reasonable person in the patient''s position would want to know to make an informed choice", "Is always fatal", "Is only related to surgery"]', 1, 'Materiality is based on the significance of the information to the decision-maker.'),
    (v_topic_id, 'Does a patient need to sign a new consent form if a *different* surgeon in the same group performs the same procedure they originally consented to?', '["No, consent is for the procedure", "Yes, the patient must consent to the specific person performing the procedure", "Only if the first surgeon is dead", "Only if the surgery is on a limb"]', 1, 'Consent is not just for the "what" but for the "who." If the surgeon changes, the patient should be informed and agree to the change.'),
    (v_topic_id, 'Which of the following is true about "Oral Consent"?', '["It is never legally valid", "It is legally valid but more difficult to prove than written consent", "It is only valid for children", "It must be recorded on video to be valid"]', 1, 'Consent is the *process* of communication; the form is just the evidence of that process. Oral consent is valid but risky for documentation.'),
    (v_topic_id, 'A patient asks about the physician''s experience level with a particular high-risk procedure. According to some court rulings, should this be disclosed?', '["No, that is private information", "Yes, if it is a material factor that a reasonable patient would use to decide whether to proceed", "Only if the doctor is a resident", "Only if the patient asks three times"]', 1, 'Transparency about experience and success rates is increasingly considered part of adequate disclosure for high-risk interventions.'),
    (v_topic_id, 'A physician is performing a surgery and finds a *second* unrelated problem that needs correction. If it is NOT an emergency, can they fix it while the patient is still under anesthesia?', '["Yes, it saves the patient another surgery", "No, they must wait until the patient is awake to obtain specific consent for the new procedure", "Only if the family is in the waiting room", "Only if it takes less than 10 minutes"]', 1, 'Non-emergent "extension" of a procedure without prior consent is a violation of autonomy and can be considered "battery" in some jurisdictions.'),
    (v_topic_id, 'Which principle is the primary ethical basis for the requirement of informed consent?', '["Justice", "Beneficence", "Autonomy", "Non-maleficence"]', 2, 'Informed consent is the practical application of the principle of Respect for Autonomy.'),
    (v_topic_id, 'A patient with a terminal illness is in a clinical trial. They want to withdraw halfway through. The researcher should:', '["Refuse, because the patient signed a contract", "Allow the withdrawal immediately without penalty", "Charge the patient for the wasted medications", "Tell the patient they will die sooner"]', 1, 'Autonomy includes the right to withdraw consent at any time, especially in research.'),
    (v_topic_id, 'When is "Implied Consent" sufficient for a physical exam?', '["Never, you must always ask", "When a patient extends their arm for a blood pressure cuff or blood draw after being told what is happening", "Only in the ICU", "Only for unconscious patients"]', 1, 'Behavioral cues that demonstrate agreement can constitute implied consent for routine, non-invasive procedures.'),
    (v_topic_id, 'A patient is given a 10-page technical document to read as their "disclosure." They don''t understand it. Is this valid informed consent?', '["Yes, the information was provided", "No, because the ''Comprehension'' (Understanding) element is missing", "Yes, if they signed it", "Only if it was written in English"]', 1, 'Disclosure is not enough; the information must be presented in a way that the patient can actually understand (e.g., appropriate language, literacy level).'),
    (v_topic_id, 'Which of the following is an example of "Undue Influence" in consent?', '["Explaining that the alternative to surgery is death", "A doctor telling a patient they will ''fire'' them if they don''t join a research study", "Providing a second opinion", "Showing a diagram of the heart"]', 1, 'Undue influence occurs when a person in power uses a threat or incentive to compromise a patient''s voluntary choice.'),
    (v_topic_id, 'In the context of "Informed Refusal," what must the physician specifically disclose?', '["The benefits of the treatment", "The specific risks and consequences of NOT having the treatment", "The names of other patients who refused", "The cost of the burial"]', 1, 'Just like consent, refusal must be informed. The patient must understand what they are giving up.'),
    (v_topic_id, 'A patient refuses a life-saving procedure. The physician believes the patient is making a "wrong" decision. Does this mean the patient lacks capacity?', '["Yes, rational people choose life", "No, a competent patient has the right to make decisions that others might perceive as irrational", "Only if the patient is over 70", "Only if the patient is a minor"]', 1, 'Capacity is about the *process* of decision-making, not the *outcome*.'),
    (v_topic_id, 'A physician is working in a teaching hospital. Do they need to disclose that a resident will be performing a major part of the surgery?', '["No, all doctors are the same", "Yes, as this is a material fact regarding the care being provided", "Only if the resident is in their first year", "Only if the surgery is free"]', 1, 'The role of learners in the care team is part of the "Who" of informed consent.'),
    (v_topic_id, 'A patient is being treated for a highly contagious, dangerous disease (e.g., active Ebola) and refuses isolation. Can they be treated/isolated against their will?', '["No, autonomy is absolute", "Yes, the ''Police Power'' of the state to protect public health can override individual autonomy in specific cases of serious public threat", "Only if they have a surrogate", "Only if they are in the military"]', 1, 'Public health safety is one of the few legal overrides to individual medical autonomy.'),
    (v_topic_id, 'Which of the following is true regarding "Blanket" consent forms signed upon admission to a hospital?', '["They cover all major surgeries during the stay", "They generally only cover routine care (nursing, basic labs, imaging) and do not replace specific consent for invasive procedures", "They are legally worthless", "They allow the hospital to do anything they want"]', 1, 'Specific, high-risk procedures always require their own dedicated informed consent process.'),
    (v_topic_id, 'A patient is in a clinical trial and the researcher discovers a new, safer alternative is now available. What should the researcher do?', '["Nothing, it might ruin the study data", "Inform the patient of the new alternative, as part of the ''ongoing'' nature of informed consent", "Wait until the study is over", "None of the above"]', 1, 'Informed consent is a continuous process, not a one-time event.'),
    (v_topic_id, 'What is the "Subjective Standard" for disclosure (rarely used in law)?', '["What the medical community says", "What a reasonable patient says", "What this *specific* patient, with their unique values and needs, would want to know", "What the doctor says"]', 2, 'The subjective standard is ethically ideal but legally difficult to apply as it requires knowing the patient''s internal thoughts.'),
    (v_topic_id, 'A patient is being treated for a psychiatric condition and is currently "Involuntarily Committed." Does this automatically mean they lack capacity to consent to or refuse medical treatments (like an appendectomy)?', '["Yes, commitment implies incompetence", "No, involuntary commitment is for safety/mental health care, but a separate assessment is needed for capacity for medical decisions", "Only if they have schizophrenia", "Only if they are on a ''72-hour hold"]', 1, 'Capacity is decision-specific. A patient can be committed for mental health reasons but still have the capacity to make other medical decisions.'),
    (v_topic_id, 'A physician is worried about a lawsuit and decides to list *every* single theoretical risk (thousands) to a patient. This is:', '["Good defensive medicine", "Potentially harmful as it can overwhelm the patient and hinder true understanding (information overload)", "Required by HIPAA", "None of the above"]', 1, 'Information overload can actually undermine the goal of "understanding" in informed consent.'),
    (v_topic_id, 'Which of the following is an example of "Implied Consent" in an non-emergency?', '["A patient showing up for a scheduled colonoscopy", "A patient nodding when asked if they want a flu shot", "A patient staying silent when told they need a catheter", "None of the above"]', 1, 'Non-verbal affirmative cues in response to a request can constitute implied consent.'),
    (v_topic_id, 'A "Proxy" decision-maker should prioritize which standard above all others?', '["Best Interests", "Substituted Judgment (what the patient would have wanted)", "The Physician''s Recommendation", "The Spouse''s preference"]', 1, 'Substituted judgment is the primary standard for surrogates of previously competent patients.'),
    (v_topic_id, 'If a patient has *never* been competent (e.g., a child or person with severe lifelong cognitive disability), which standard must the surrogate use?', '["Substituted Judgment", "Best Interests Standard", "Subjective Standard", "None of the above"]', 1, 'Since there is no "prior self" to reference, the surrogate must choose what is objectively best for the patient.'),
    (v_topic_id, 'A patient is allergic to a life-saving medication. The physician believes the risk of the reaction is lower than the risk of the disease. The patient refuses. The physician should:', '["Give it anyway", "Respect the refusal as long as the patient has capacity and understands the risks", "Ask the court to overrule the patient", "Tell the patient they are being stupid"]', 1, 'Competent patients have the right to refuse even life-saving treatments.'),
    (v_topic_id, 'Which of the following is true about "Paralysis by Analysis" in informed consent?', '["It is a type of anesthesia", "It refers to a patient being unable to choose because they have been given too much data to process", "It is required for brain surgery", "None of the above"]', 1, 'Providing too much irrelevant detail can be as bad as providing too little.'),
    (v_topic_id, 'The "Four Pillars" of medical ethics are Autonomy, Beneficence, Non-maleficence, and Justice. Which is most directly challenged by "Paternalism"?', '["Justice", "Non-maleficence", "Autonomy", "None of the above"]', 2, 'Paternalism involves overriding a patient''s autonomy for their "own good" (beneficence).'),
    (v_topic_id, 'A patient is a Jehovah''s Witness and refuses a blood transfusion. Is this a valid informed refusal?', '["No, it''s a religious myth", "Yes, if they are competent and understand the consequences, their religious values must be respected", "Only if they have a signed card", "Only if they are over 50"]', 1, 'Autonomy includes the right to make decisions based on one''s own religious or philosophical beliefs.'),
    (v_topic_id, 'A physician is performing a research study and offers a homeless patient $5000 to participate. This is potentially:', '["Coercion", "Undue Inducement", "Benevolence", "None of the above"]', 1, 'Undue inducement occurs when an offer is so attractive that it might cloud the patient''s judgment about risks.'),
    (v_topic_id, 'Does a patient have a right to "Informed Consent" for a treatment that the physician believes is "Medically Futile" (offers no physiological benefit)?', '["Yes, they can demand anything", "No, a patient cannot demand that a physician provide non-beneficial or harmful care", "Only if they pay cash", "Only in the ICU"]', 1, 'Autonomy is a "Negative Right" (the right to be left alone or refuse), not a "Positive Right" to demand any specific treatment.'),
    (v_topic_id, 'A "Wait and See" approach is often a valid alternative to an intervention. Should it be disclosed?', '["No, it''s not a treatment", "Yes, ''doing nothing'' is a valid ''Alternative'' that must be disclosed as part of the options", "Only if the patient asks", "None of the above"]', 1, 'The risks and benefits of the status quo (no treatment) are essential for comparison.'),
    (v_topic_id, 'A patient is being treated in a "Language they don''t speak." For consent to be valid, the physician must:', '["Use the patient''s 10-year-old child to translate", "Use a qualified medical interpreter", "Speak louder", "Use Google Translate only"]', 1, 'Using family members (especially children) is unprofessional and can lead to misunderstandings or coercion. A qualified interpreter is required for valid consent.'),
    (v_topic_id, 'Which of the following describes "Assent"?', '["The legal agreement of an adult", "The agreement of someone (like a child) who cannot legally provide consent but can still participate in the decision-making process", "A type of court order", "None of the above"]', 1, 'Assent is ethically important for respecting the developing autonomy of minors.'),
    (v_topic_id, 'A physician is sued for "Battery" because they performed a procedure without *any* consent. Battery is a:', '["Violation of privacy", "Unconsented, offensive physical contact", "Failure to follow the standard of care", "None of the above"]', 1, 'Battery is an intentional tort that doesn''t require proof of harm, just lack of consent.'),
    (v_topic_id, 'A physician is sued for "Negligence" because they provided consent but didn''t mention a specific risk. Negligence requires:', '["A bad attitude", "Proof that the missing information would have changed the patient''s decision and caused harm", "No signed form", "None of the above"]', 1, 'Informed consent lawsuits under a negligence theory require proving "Causation" (that the patient would have chosen differently if they had known).'),
    (v_topic_id, 'In an "Emergency" exception, if the patient''s family arrives *after* the surgery has started, the physician should:', '["Ignore them", "Update them as soon as possible and obtain consent for any *further* treatments", "Stop the surgery immediately", "None of the above"]', 1, 'Consent should be obtained as soon as a surrogate becomes available.'),
    (v_topic_id, 'A patient is being asked to participate in a "Blind" study. They must be told:', '["Everything except the name of the drug", "That they might receive a placebo or a different dose, and the risks of both", "Nothing, that''s why it''s blind", "None of the above"]', 1, 'The *fact* that the study is blinded and the *nature* of the random assignment must be disclosed.'),
    (v_topic_id, 'A "Mandatory" vaccination program is justified by which ethical principle?', '["Autonomy", "Justice (Common Good/Public Health)", "Veracity", "None of the above"]', 1, 'Public health ethics often balance individual autonomy against the justice of protecting the community.'),
    (v_topic_id, 'A physician provides a "Biased" presentation of data to nudge a patient toward a specific choice. This is:', '["Good counseling", "Manipulation, which undermines the ''Voluntariness'' of consent", "Required by the hospital", "None of the above"]', 1, 'Presenting information fairly is key to respecting the patient''s right to choose.'),
    (v_topic_id, 'Which of the following is true about "Consent for Organ Donation" in the US?', '["It is ''Opt-out'' (everyone is a donor unless they say no)", "It is ''Opt-in'' (individuals must explicitly choose to be a donor)", "It is mandatory", "None of the above"]', 1, 'The US uses an "active-in" system, though family consent is often sought if the patient''s wishes are unknown.'),
    (v_topic_id, 'The final check before starting a procedure (Time-Out) involves verifying the patient''s identity, the site, and:', '["The surgeon''s lunch", "That informed consent has been obtained and documented", "The patient''s credit score", "None of the above"]', 1, 'Verifying consent is a standard safety requirement before any invasive action.');
